//! A writer, NOT a general C14N implementation. Every emitted element has an
//! explicit end tag, only the root uses a namespace, text is C14N-escaped, and
//! there are no comments, PIs, DTDs, inherited xml:* attributes or default NSs.
//! Consequently these generated bytes equal Exclusive C14N 1.0. Never feed an
//! arbitrary XML document to this signer. SOAP is added AFTER signing the record.
use crate::{vero_filing::VeroCredentials, AdapterError, CredentialHandle};
use aggountant_domain::{
    payroll::{EmployerReportAction, EmployerSeparateReport},
    validate_hetu, TravelLine, WageCorrection, WageCorrectionAction, WageReport,
};
use aggountant_model::Instant;
use base64::{engine::general_purpose::STANDARD, Engine};
use ring::{rand::SystemRandom, signature};
use sha2::{Digest, Sha256};
use x509_parser::{parse_x509_certificate, pem::parse_x509_pem};

const DS: &str = "http://www.w3.org/2000/09/xmldsig#";
const C14N: &str = "http://www.w3.org/2001/10/xml-exc-c14n#";
pub const WAGE_NS: &str = "http://www.tulorekisteri.fi/2017/1/WageReportsToIR";
pub const STATUS_NS: &str = "http://www.tulorekisteri.fi/2017/1/StatusRequestToIR";
/// Employer's separate report, schema `PayerSummaryReportsToIR` (vendored under
/// `crates/broker/schemas/tulorekisteri/`).
pub const PSR_NS: &str = "http://www.tulorekisteri.fi/2017/1/PayerSummaryReportsToIR";
/// `DeliveryDataType` codes: earnings payment reports and employer's separate reports.
pub const DELIVERY_TYPE_WAGE: &str = "100";
pub const DELIVERY_TYPE_EMPLOYER: &str = "101";
/// Cancellation of earnings payment reports.
pub const DELIVERY_TYPE_WAGE_CANCELLATION: &str = "105";
pub const INVALIDATION_NS: &str = "http://www.tulorekisteri.fi/2017/1/InvalidationsToIR";
fn bad() -> AdapterError {
    AdapterError::Malformed("invalid Tulorekisteri signing material or record".into())
}
fn text(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('\r', "&#xD;")
}
fn e(name: &str, s: &str) -> String {
    format!("<{name}>{}</{name}>", text(s))
}
fn id(kind: &str, code: &str) -> String {
    format!("<Id>{}{}</Id>", e("Type", kind), e("Code", code))
}
fn actors(business_id: &str) -> String {
    [
        "DeliveryDataOwner",
        "DeliveryDataCreator",
        "DeliveryDataSender",
    ]
    .iter()
    .map(|n| format!("<{n}>{}{}</{n}>", e("Type", "1"), e("Code", business_id)))
    .collect()
}
/// Offline, no credential required. HETU never appears in an error or preview.
pub fn wage_record(
    report: &WageReport,
    hetu: &str,
    timestamp: Instant,
) -> Result<String, AdapterError> {
    let report_data = e("ActionCode", "1") + &e("ReportId", &report.report_id());
    wage_report_record(report, hetu, timestamp, &report.delivery_id(), &report_data)
}
/// A replacement of the report the register holds as `ir_report_id` (`ActionCode`
/// 2): the whole report again in its own record. The pay period, the payer and the
/// income earner must repeat the previous version (Data delivery – Schemas –
/// Earnings payment reports 2026, §2.1, §2.4 and §2.13); the caller checks that.
pub fn wage_replacement_record(
    correction: &WageCorrection,
    hetu: &str,
    timestamp: Instant,
) -> Result<String, AdapterError> {
    correction
        .validate(timestamp.utc_date())
        .map_err(|_| bad())?;
    if correction.action != WageCorrectionAction::Replacement {
        return Err(bad());
    }
    let report_data = e("ActionCode", "2")
        + &e("IRReportId", &correction.ir_report_id)
        + &correction
            .corrects_version
            .map(|v| e("ReportVersion", &v.to_string()))
            .unwrap_or_default();
    wage_report_record(
        &correction.report,
        hetu,
        timestamp,
        &correction.delivery_id(timestamp),
        &report_data,
    )
}
/// Cancellation of one report (`InvalidationRequestToIR`), found by the register's
/// report reference and, when known, its latest version. `delivery_data_type` is
/// the cancellation's own record type. Offline, no PII. Element order and the
/// mandatory `Source` and `FaultyControl` follow InvalidationsToIRTypes.xsd and
/// Data delivery – Schemas – Cancellation data 2026, §2.1–2.2.
pub fn invalidation_record(
    delivery_data_type: &str,
    delivery_id: &str,
    business_id: &str,
    ir_report_id: &str,
    version: Option<u32>,
    timestamp: Instant,
) -> String {
    let item = e("IRItemId", ir_report_id)
        + &version
            .map(|v| e("ItemVersion", &v.to_string()))
            .unwrap_or_default();
    format!(
        "<ir:InvalidationRequestToIR xmlns:ir=\"{INVALIDATION_NS}\"><DeliveryData>{}{}{}{}{}{}{}<Items><Item>{item}</Item></Items></DeliveryData></ir:InvalidationRequestToIR>",
        e("Timestamp", &timestamp.to_string()),
        e("Source", "aggountant"),
        e("DeliveryDataType", delivery_data_type),
        e("DeliveryId", delivery_id),
        e("FaultyControl", "2"),
        e("ProductionEnvironment", "true"),
        actors(business_id)
    )
}
fn wage_report_record(
    report: &WageReport,
    hetu: &str,
    timestamp: Instant,
    delivery_id: &str,
    report_data: &str,
) -> Result<String, AdapterError> {
    report.validate(timestamp.utc_date()).map_err(|_| bad())?;
    validate_hetu(hetu)
        .map_err(|_| AdapterError::Malformed("invalid income earner HETU in PII store".into()))?;
    let mut data = e("Timestamp", &timestamp.to_string());
    data += &e("Source", "aggountant");
    data += &e("DeliveryDataType", DELIVERY_TYPE_WAGE);
    data += &e("DeliveryId", delivery_id);
    data += &e("FaultyControl", "2");
    data += &e("ProductionEnvironment", "true");
    data += &actors(report.business_id.as_str());
    data += &format!(
        "<PaymentPeriod>{}{}{}</PaymentPeriod>",
        e("PaymentDate", &report.payment_date.to_string()),
        e("StartDate", &report.period_start.to_string()),
        e("EndDate", &report.period_end.to_string())
    );
    data += &format!(
        "<ContactPersons><ContactPerson>{}{}</ContactPerson></ContactPersons>",
        e("Name", report.contact_name.as_str()),
        e("Telephone", report.contact_phone.as_str())
    );
    data += &format!(
        "<Payer><PayerIds>{}</PayerIds></Payer>",
        id("1", report.business_id.as_str())
    );
    data += &format!(
        "<Reports><Report><ReportData>{report_data}</ReportData><IncomeEarner><IncomeEarnerIds>{}</IncomeEarnerIds>",
        id("2", hetu)
    );
    if report.joint_owner {
        data += "<IncomeEarnerOther><IncomeEarnerTypes><IncomeEarnerType>2</IncomeEarnerType></IncomeEarnerTypes></IncomeEarnerOther>";
    }
    data += "</IncomeEarner><Transactions>";
    for line in &report.lines {
        data += &format!(
            "<Transaction><TransactionBasic>{}{}</TransactionBasic>",
            e("TransactionCode", line.code()),
            e("Amount", &line.amount())
        );
        data += &match line {
            TravelLine::Kilometres { kilometers, .. } => format!(
                "<KmAllowance>{}</KmAllowance>",
                e("Kilometers", &kilometers.to_string())
            ),
            TravelLine::DailyAllowance { allowance_code, .. } => format!(
                "<DailyAllowance>{}</DailyAllowance>",
                e("AllowanceCode", &allowance_code.to_string())
            ),
        };
        data += "</Transaction>";
    }
    data += "</Transactions></Report></Reports>";
    Ok(format!("<ir:WageReportRequestToIR xmlns:ir=\"{WAGE_NS}\"><DeliveryData>{data}</DeliveryData></ir:WageReportRequestToIR>"))
}
/// Employer's separate report record (`PayerSummaryReportRequestToIR`), one report.
/// Offline, no PII. Element order and names follow PayerSummaryReportsToIRTypes.xsd.
pub fn payer_summary_record(
    report: &EmployerSeparateReport,
    timestamp: Instant,
) -> Result<String, AdapterError> {
    report.validate().map_err(|_| bad())?;
    let business_id = report.business_id.as_str();
    let mut data = e("Timestamp", &timestamp.to_string());
    data += &e("Source", "aggountant");
    data += &e("DeliveryDataType", DELIVERY_TYPE_EMPLOYER);
    data += &e("DeliveryId", &report.delivery_id(timestamp));
    data += &e("FaultyControl", "2");
    data += &e("ProductionEnvironment", "true");
    data += &actors(business_id);
    data += &format!(
        "<ContactPersons><ContactPerson>{}{}</ContactPerson></ContactPersons>",
        e("Name", report.contact_name.as_str()),
        e("Telephone", report.contact_phone.as_str())
    );
    data += &e("ReportDate", &timestamp.utc_date().to_string());
    data += &format!("<Payer><PayerIds>{}</PayerIds>", id("1", business_id));
    let pensions = report.sent_pension_insurances();
    if !pensions.is_empty() {
        data += "<PensionInsurances>";
        for p in pensions {
            data += &format!(
                "<PensionInsurance>{}{}</PensionInsurance>",
                e("PensionProvIdCode", &p.provider_code.to_string()),
                e("PensionPolicyNo", &p.policy_number)
            );
        }
        data += "</PensionInsurances>";
    }
    data += "</Payer><Reports><Report><ReportData>";
    data += &match &report.action {
        EmployerReportAction::New => e("ActionCode", "1") + &e("ReportId", &report.report_id()),
        EmployerReportAction::Replacement {
            ir_report_id,
            replaces_version,
        } => {
            e("ActionCode", "2")
                + &e("IRReportId", ir_report_id)
                + &replaces_version
                    .map(|v| e("ReportVersion", &v.to_string()))
                    .unwrap_or_default()
        }
    };
    data += &format!(
        "</ReportData><PaymentMonth>{}{}</PaymentMonth>",
        e("Month", &report.month.month().to_string()),
        e("Year", &report.month.year().to_string())
    );
    let (code, amount) = report.content.transaction();
    data += &format!(
        "<Transactions><Transaction><TransactionBasic>{}{}</TransactionBasic></Transaction></Transactions>",
        e("SummaryTransactionCode", code),
        amount.map(|a| e("Amount", a)).unwrap_or_default()
    );
    data += "</Report></Reports>";
    Ok(format!("<ir:PayerSummaryReportRequestToIR xmlns:ir=\"{PSR_NS}\"><DeliveryData>{data}</DeliveryData></ir:PayerSummaryReportRequestToIR>"))
}
/// Signed processing-feedback request for one record of either report type.
pub fn status_record(
    delivery_data_type: &str,
    delivery_id: &str,
    business_id: &str,
    timestamp: Instant,
) -> String {
    format!(
        "<ir:StatusRequestToIR xmlns:ir=\"{STATUS_NS}\">{}{}{}{}{}</ir:StatusRequestToIR>",
        e("Timestamp", &timestamp.to_string()),
        e("DeliveryDataType", delivery_data_type),
        e("DeliveryId", delivery_id),
        e("ProductionEnvironment", "true"),
        actors(business_id)
    )
}
fn signed_info(digest: &str) -> String {
    format!("<ds:SignedInfo xmlns:ds=\"{DS}\"><ds:CanonicalizationMethod Algorithm=\"{C14N}\"></ds:CanonicalizationMethod><ds:SignatureMethod Algorithm=\"http://www.w3.org/2001/04/xmldsig-more#rsa-sha256\"></ds:SignatureMethod><ds:Reference URI=\"\"><ds:Transforms><ds:Transform Algorithm=\"{DS}enveloped-signature\"></ds:Transform><ds:Transform Algorithm=\"{C14N}\"></ds:Transform></ds:Transforms><ds:DigestMethod Algorithm=\"http://www.w3.org/2001/04/xmlenc#sha256\"></ds:DigestMethod><ds:DigestValue>{digest}</ds:DigestValue></ds:Reference></ds:SignedInfo>")
}
/// The RSA key records are signed with: PKCS#8 or PKCS#1 PEM. Readiness loads it
/// too, so a bundle the transport accepts but signing cannot use is a blocker
/// rather than a refusal at send time.
pub(crate) fn signing_key(
    credentials: &VeroCredentials,
) -> Result<signature::RsaKeyPair, AdapterError> {
    let key_pem = &credentials.client_private_key_pem;
    let (label, pkcs8) = if key_pem.starts_with("-----BEGIN PRIVATE KEY-----") {
        ("PRIVATE KEY", true)
    } else {
        ("RSA PRIVATE KEY", false)
    };
    let base64 = key_pem
        .strip_prefix(&format!("-----BEGIN {label}-----"))
        .and_then(|s| s.trim().strip_suffix(&format!("-----END {label}-----")))
        .ok_or_else(bad)?;
    let key_der = STANDARD
        .decode(
            base64
                .chars()
                .filter(|c| !c.is_ascii_whitespace())
                .collect::<String>(),
        )
        .map_err(|_| bad())?;
    if pkcs8 {
        signature::RsaKeyPair::from_pkcs8(&key_der)
    } else {
        signature::RsaKeyPair::from_der(&key_der)
    }
    .map_err(|_| bad())
}
/// Called only on this module's generated records. The adapter reconstructs them
/// from validated input, rather than signing caller-supplied XML.
pub(crate) fn sign_record(record: &str, handle: &CredentialHandle) -> Result<String, AdapterError> {
    let credentials = VeroCredentials::parse(handle.expose_secret()).map_err(|_| bad())?;
    let key = signing_key(&credentials)?;
    let (_, cert) =
        parse_x509_pem(credentials.client_certificate_pem.as_bytes()).map_err(|_| bad())?;
    let (_, parsed) = parse_x509_certificate(&cert.contents).map_err(|_| bad())?;
    let info = signed_info(&STANDARD.encode(Sha256::digest(record.as_bytes())));
    let mut sig = vec![0; key.public().modulus_len()];
    key.sign(
        &signature::RSA_PKCS1_SHA256,
        &SystemRandom::new(),
        info.as_bytes(),
        &mut sig,
    )
    .map_err(|_| bad())?;
    // Fail closed for mismatched certificate/key, not just a syntactically valid key.
    signature::UnparsedPublicKey::new(
        &signature::RSA_PKCS1_2048_8192_SHA256,
        parsed.public_key().subject_public_key.data.as_ref(),
    )
    .verify(info.as_bytes(), &sig)
    .map_err(|_| bad())?;
    let signature = format!("<ds:Signature xmlns:ds=\"{DS}\">{}<ds:SignatureValue>{}</ds:SignatureValue><ds:KeyInfo><ds:X509Data><ds:X509Certificate>{}</ds:X509Certificate></ds:X509Data></ds:KeyInfo></ds:Signature>",info.replace(&format!(" xmlns:ds=\"{DS}\""),""),STANDARD.encode(sig),STANDARD.encode(&cert.contents));
    let end = record.rfind("</ir:").ok_or_else(bad)?;
    Ok(format!("{}{}{}", &record[..end], signature, &record[end..]))
}
pub fn record_hash(record: &str) -> String {
    hex::encode(Sha256::digest(record.as_bytes()))
}
pub fn soap(record: &str) -> String {
    format!("<soap:Envelope xmlns:soap=\"http://schemas.xmlsoap.org/soap/envelope/\"><soap:Body>{record}</soap:Body></soap:Envelope>")
}
